1	/**
2	 * What MHPCO knows about the customer's standing: the facts of their history
3	 * with the office that its policy-wide discount rules are written against.
4	 */
5	export interface Customer {
6	  yearsWithMHPCO: number;
7	  /** Contracts this customer already holds, before the one being quoted. */
8	  previousContracts?: number;
9	}
10	
11	export interface Item {
12	  type: string;
13	  cursed?: boolean;
14	  enchantment?: number;
15	}
16	
17	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
18	  sword: 100,
19	  amulet: 60,
20	  staff: 80,
21	  potion: 40,
22	};
23	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
24	const COMPONENT_BASE_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_BASE_PREMIUM = 60;
27	const CURSE_SURCHARGE_RATE = 0.5;
28	const HIGH_ENCHANTMENT_LEVEL = 5;
29	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
30	const LOYALTY_YEARS = 2;
31	const LOYALTY_DISCOUNT_RATE = 0.2;
32	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
33	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
34	const PROCESSING_FEE = 5;
35	
36	function isComponent(item: Item): boolean {
37	  return COMPONENT_TYPES.has(item.type);
38	}
39	
40	function isMainItem(item: Item): boolean {
41	  return !isComponent(item);
42	}
43	
44	function mainItemBasePremium(item: Item): number {
45	  const basePremium = MAIN_ITEM_BASE_PREMIUMS[item.type];
46	  if (basePremium === undefined) {
47	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
48	  }
49	  return basePremium;
50	}
51	
52	function alikeGroupBasePremium(count: number): number {
53	  return count === BLOCK_SIZE
54	    ? BLOCK_BASE_PREMIUM
55	    : count * COMPONENT_BASE_PREMIUM;
56	}
57	
58	/** Components are "alike" when they are of exactly the same type. */
59	function alikeKey(component: Item): string {
60	  return component.type;
61	}
62	
63	function componentsBasePremium(components: Item[]): number {
64	  const countsPerAlikeGroup = new Map<string, number>();
65	  for (const component of components) {
66	    const key = alikeKey(component);
67	    countsPerAlikeGroup.set(key, (countsPerAlikeGroup.get(key) ?? 0) + 1);
68	  }
69	  return [...countsPerAlikeGroup.values()].reduce(
70	    (total, count) => total + alikeGroupBasePremium(count),
71	    0,
72	  );
73	}
74	
75	function curseSurcharge(item: Item): number {
76	  return item.cursed === true
77	    ? mainItemBasePremium(item) * CURSE_SURCHARGE_RATE
78	    : 0;
79	}
80	
81	function isHighlyEnchanted(item: Item): boolean {
82	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
83	}
84	
85	function highEnchantmentSurcharge(item: Item): number {
86	  return isHighlyEnchanted(item)
87	    ? mainItemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
88	    : 0;
89	}
90	
91	/**
92	 * Item-specific modifiers apply to the base premium of the affected item and
93	 * are added to it, never multiplied onto it. Each risk rule is independent:
94	 * its own condition, its own rate.
95	 */
96	function itemSpecificModifiers(item: Item): number {
97	  return curseSurcharge(item) + highEnchantmentSurcharge(item);
98	}
99	
100	function mainItemsBasePremium(mainItems: Item[]): number {
101	  return mainItems.reduce((total, item) => total + mainItemBasePremium(item), 0);
102	}
103	
104	/** The policy base premium: the sum of all unmodified item base premiums. */
105	function policyBasePremiumFor(items: Item[]): number {
106	  return (
107	    mainItemsBasePremium(items.filter(isMainItem)) +
108	    componentsBasePremium(items.filter(isComponent))
109	  );
110	}
111	
112	/** The item-specific surcharges of every affected item, summed. */
113	function itemSpecificModifiersFor(items: Item[]): number {
114	  return items
115	    .filter(isMainItem)
116	    .reduce((total, item) => total + itemSpecificModifiers(item), 0);
117	}
118	
119	/**
120	 * Rounding in the MHPCO's favour is a single policy with two arms: an amount
121	 * the customer pays goes up, an amount MHPCO pays out goes down. This is the
122	 * premium arm; it is named for the amount it rounds so that a payout can never
123	 * reach it by mistake.
124	 */
125	function roundPremiumInMHPCOsFavour(premium: number): number {
126	  return Math.ceil(premium);
127	}
128	
129	/** Every item in a quote is treated as a first insurance. */
130	function firstInsuranceSurcharge(policyBasePremium: number): number {
131	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
132	}
133	
134	function isLongStanding(customer: Customer): boolean {
135	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
136	}
137	
138	function loyaltyDiscount(customer: Customer, policyBasePremium: number): number {
139	  return isLongStanding(customer)
140	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
141	    : 0;
142	}
143	
144	function isFollowUpContract(customer: Customer): boolean {
145	  return (customer.previousContracts ?? 0) > 0;
146	}
147	
148	function followUpDiscount(
149	  customer: Customer,
150	  policyBasePremium: number,
151	): number {
152	  return isFollowUpContract(customer)
153	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
154	    : 0;
155	}
156	
157	/**
158	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
159	 * base premiums) and are added to it, never multiplied onto it. Each rule is
160	 * independent: its own condition, its own rate. Surcharges raise the premium
161	 * and discounts lower it; each is computed as a positive amount off the
162	 * unmodified policy base premium and given its sign here.
163	 */
164	function policyWideModifiers(
165	  customer: Customer,
166	  policyBasePremium: number,
167	): number {
168	  return (
169	    firstInsuranceSurcharge(policyBasePremium) -
170	    loyaltyDiscount(customer, policyBasePremium) -
171	    followUpDiscount(customer, policyBasePremium)
172	  );
173	}
174	
175	export function quote(customer: Customer, items: Item[]): number {
176	  const policyBasePremium = policyBasePremiumFor(items);
177	  const premium =
178	    policyBasePremium +
179	    itemSpecificModifiersFor(items) +
180	    policyWideModifiers(customer, policyBasePremium) +
181	    PROCESSING_FEE;
182	  return roundPremiumInMHPCOsFavour(premium);
183	}
184

