151	  return Math.ceil(premium);
152	}
153	
154	/** Every item in a quote is treated as a first insurance. */
155	function firstInsuranceSurcharge(policyBasePremium: number): number {
156	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
157	}
158	
159	function isLongStanding(customer: Customer): boolean {
160	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
161	}
162	
163	function loyaltyDiscount(customer: Customer, policyBasePremium: number): number {
164	  return isLongStanding(customer)
165	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
166	    : 0;
167	}
168	
169	function isFollowUpContract(customer: Customer): boolean {
170	  return (customer.previousContracts ?? 0) > 0;
171	}
172	
173	function followUpDiscount(
174	  customer: Customer,
175	  policyBasePremium: number,
176	): number {
177	  return isFollowUpContract(customer)
178	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
179	    : 0;
180	}
181	
182	/**
183	 * Policy-wide modifiers apply to the policy base premium (the sum of all item
184	 * base premiums) and are added to it, never multiplied onto it. Each rule is
185	 * independent: its own condition, its own rate. Surcharges raise the premium
186	 * and discounts lower it; each is computed as a positive amount off the
187	 * unmodified policy base premium and given its sign here.
188	 */
189	function policyWideModifiers(
190	  customer: Customer,
191	  policyBasePremium: number,
192	): number {
193	  return (
194	    firstInsuranceSurcharge(policyBasePremium) -
195	    loyaltyDiscount(customer, policyBasePremium) -
196	    followUpDiscount(customer, policyBasePremium)
197	  );
198	}
199	
200	export function quote(customer: Customer, items: Item[]): number {
201	  const policyBasePremium = policyBasePremiumFor(items);
202	  const premium =
203	    policyBasePremium +
204	    itemSpecificModifiersFor(items) +
205	    policyWideModifiers(customer, policyBasePremium) +
206	    PROCESSING_FEE;
207	  return roundPremiumInMHPCOsFavour(premium);
208	}

